-- public.cellar_flight_onto(p_world uuid, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.cellar_flight_onto(p_world uuid, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select f.kind from floor_tile f
   where f.world_id = p_world and f.level = 0 and f.kind in ('stairs', 'ladder')
     and exists (select 1 from cellar_tile c where c.world_id = p_world and c.x = f.x and c.y = f.y)
     and ((f.x = p_x and f.y = p_y)
          or (f.hand is distinct from 's'
              and (f.x, f.y, coalesce(f.facing, 's')) in ((p_x, p_y + 1, 'n'), (p_x - 1, p_y, 'e'), (p_x, p_y - 1, 's'), (p_x + 1, p_y, 'w'))))
   order by (f.x = p_x and f.y = p_y) desc, f.y, f.x limit 1
$function$
